// Vectors generated by the server's own verifier (cusd_plus/hl_signing.py,
// itself pinned to the official SDK's published vectors): if the app and the
// server ever disagree on a byte, the server refuses the member's action.
import { bytesToHex } from '@noble/hashes/utils';

import {
  actionHash,
  msgpackEncode,
  nextNonce,
  signAction,
  signRelayNonceMapping,
} from '../hyperliquidSigning';

const vectors = require('./fixtures/hyperliquidVectors.json');
const SDK_KEY = '0123456789012345678901234567890123456789012345678901234567890123';
// Python's hex() drops leading zeros; the server parses r/s as integers.
const norm = (sig: { r: string; s: string; v: number }) => ({ r: BigInt(sig.r), s: BigInt(sig.s), v: sig.v });

describe('hyperliquid signing', () => {
  it.each(['order', 'lev', 'iso', 'tpsl', 'noop'])('L1 %s: msgpack, hash and signature match the server', (name) => {
    const v = vectors[name];
    expect(bytesToHex(msgpackEncode(v.action))).toBe(v.msgpack);
    expect('0x' + bytesToHex(actionHash(v.action, v.nonce))).toBe(v.hash);
    expect(norm(signAction(v.action, v.nonce, SDK_KEY))).toEqual(norm(v.sig));
  });

  it('user-signed sendAsset and userSetAbstraction', () => {
    expect(norm(signAction(vectors.send.action, vectors.send.action.nonce, SDK_KEY))).toEqual(norm(vectors.send.sig));
    expect(norm(signAction(vectors.abstraction.action, vectors.abstraction.action.nonce, SDK_KEY)))
      .toEqual(norm(vectors.abstraction.sig));
  });

  it('refuses a user-signed action whose nonce differs from the envelope', () => {
    expect(() => signAction(vectors.send.action, vectors.send.action.nonce + 1, SDK_KEY)).toThrow();
  });

  it('Bridge2 withdrawal (Salida de emergencia)', () => {
    const v = vectors.withdraw;
    expect(norm(signAction(v.action, v.action.time, SDK_KEY))).toEqual(norm(v.sig));
  });

  it('Relay nonce mapping', () => {
    expect(norm(signRelayNonceMapping(vectors.mapping.value, 0xa4b1, SDK_KEY))).toEqual(norm(vectors.mapping.sig));
  });

  it('msgpack integer widths follow Python', () => {
    expect(bytesToHex(msgpackEncode(127))).toBe('7f');
    expect(bytesToHex(msgpackEncode(128))).toBe('cc80');
    expect(bytesToHex(msgpackEncode(65535))).toBe('cdffff');
    expect(bytesToHex(msgpackEncode(110003))).toBe('ce0001adb3');
    expect(bytesToHex(msgpackEncode(-1))).toBe('ff');
    expect(bytesToHex(msgpackEncode(-33))).toBe('d0df');
    expect(() => msgpackEncode(1.5)).toThrow();
  });

  it('nonces strictly increase', () => {
    const a = nextNonce();
    const b = nextNonce();
    expect(b).toBeGreaterThan(a);
  });
});
